  RunTestSequence(
      PressButton(kMyButton),
      WaitForShow(kResultView),
      CheckViewProperty(kResultView, &views::Label::GetText, u"Enabled"));
}

// ✅ CORRECT - unit test: validates behavior across common and edge cases
