  base::flat_map<std::string_view, NameId> map_;
  std::deque<std::string> strings_;
};

right:
// ✅ CORRECT - strings_ destroyed after map_, so string_views remain valid during map_ destruction
class NameTable {
  std::deque<std::string> strings_;
  base::flat_map<std::string_view, NameId> map_;
