body:
**Mark methods and types that perform UI work as `@MainActor`** so that async
contexts are forced to await them. Note that Tasks inherit actor isolation from
their enclosing context — adding `@MainActor` to a Task created inside an
already-`@MainActor`-isolated context is redundant.

```swift
// ❌ WRONG - redundant @MainActor on Task inside @MainActor context
@MainActor
class MyViewController: UIViewController {
  func refresh() {
    Task { @MainActor in  // Redundant — Task inherits MainActor from class
      tableView.reloadData()
    }
  }
}

// ✅ CORRECT - Task inherits @MainActor from enclosing class
@MainActor
class MyViewController: UIViewController {
  func refresh() {
    Task {
      let data = await fetchData()
      tableView.reloadData()  // Already on MainActor
    }
  }
}

// ✅ CORRECT - mark the method as @MainActor when not in an isolated context
func updateUI() async {
  let data = await fetchData()
  await tableView.reloadData()  // UITableView is NS_SWIFT_UI_ACTOR, requires await
}

@MainActor
func updateUI() async {
  let data = await fetchData()
  tableView.reloadData()  // No await needed — method is MainActor-isolated
}
```

wrong:
// ❌ WRONG - redundant @MainActor on Task inside @MainActor context
@MainActor
class MyViewController: UIViewController {
  func refresh() {
    Task { @MainActor in  // Redundant — Task inherits MainActor from class
      tableView.reloadData()
    }
  }
}

right:
// ✅ CORRECT - Task inherits @MainActor from enclosing class
@MainActor
class MyViewController: UIViewController {
  func refresh() {
    Task {
      let data = await fetchData()
      tableView.reloadData()  // Already on MainActor
    }
  }
}

// ✅ CORRECT - mark the method as @MainActor when not in an isolated context
func updateUI() async {
  let data = await fetchData()
  await tableView.reloadData()  // UITableView is NS_SWIFT_UI_ACTOR, requires await
}

@MainActor
func updateUI() async {
  let data = await fetchData()
  tableView.reloadData()  // No await needed — method is MainActor-isolated
}

