bool result = false;
service->CheckPurchaseState(
    base::BindLambdaForTesting([&](bool is_purchased) {
      result = is_purchased;
      run_loop.Quit();
    }));
run_loop.Run();
EXPECT_FALSE(result);

right:
// ✅ CORRECT - TestFuture is simpler and cleaner
base::test::TestFuture<bool> future;
service->CheckPurchaseState(future.GetCallback());
